(function(root){'use strict';
const num=(v,d=0)=>Number.isFinite(Number(v))?Number(v):d,positive=v=>Math.max(0,num(v)),count=v=>Math.floor(positive(v)),clamp=(v,max)=>Math.min(max,positive(v));
function route(from,to,data){const steps=[];let id=to;for(let i=0;i<3&&id!==from;i++){const step=data.upgrades[id];if(!step)return null;steps.unshift(step);id=step.from;}if(id!==from||!steps.length)return null;return steps;}
function journal(j,c){const qty=count(c.quantity),fame=positive(c.fame),max=positive(j.maxFame),filled=c.byFame?Math.floor(fame/Math.max(1,max)):qty;return {filled,remainder:c.byFame?fame-filled*max:0,requiredFame:filled*max,inputs:[{id:j.empty,n:filled}],outputs:[{id:j.filled,n:filled}],silver:0,extra:positive(c.fillCost)*filled};}
function enchant(from,to,c,data){const steps=route(from,to,data);if(!steps)return {valid:false,reason:'Нет игрового рецепта такого зачарования. .4 этим способом не создаётся.'};const qty=count(c.quantity),mats=new Map();for(const step of steps)for(const m of step.mats)mats.set(m.id,(mats.get(m.id)||0)+m.n*qty);return {valid:qty>0,steps,inputs:[{id:from,n:qty,quality:true},...[...mats].map(([id,n])=>({id,n}))],outputs:[{id:to,n:qty,quality:true}],silver:0,extra:positive(c.fee)*qty};}
function salvage(id,c,data){const mats=data.salvage[id];if(!mats)return {valid:false,reason:'Для предмета нет поддерживаемого рецепта разборки.'};const qty=count(c.quantity),condition=clamp(c.condition,100)/100,rate=clamp(c.salvageRate??20,100)/100;const outputs=mats.map(m=>({id:m.id,n:qty*(Object.hasOwn(c.yields||{},m.id)?positive(c.yields[m.id]):Math.floor(m.n*rate*condition+1e-9))})).filter(m=>m.n>0);return {valid:qty>0,inputs:[{id,n:qty,quality:true}],outputs,silver:positive(c.silver)*qty,extra:positive(c.fee)*qty,conservative:true};}
function mount(m,c,data){const qty=count(c.quantity),breed=data.breeders.find(b=>b.grown===m.grown);if(c.mountMode==='saddle')return {valid:qty>0,inputs:m.mats.map(x=>({...x,n:x.n*qty})),outputs:[{id:m.id,n:qty,quality:true}],silver:0,extra:(positive(c.fee)+m.silver)*qty,focus:0,hours:0,investment:positive(c.investment)};
 if(!breed)return {valid:false,reason:'Для этого маунта нет данных о выращивании.'};
 const actions=Math.min(breed.actions,count(c.nurtures)),babyReturn=qty*(breed.offspring+actions*breed.nurtureBonus),keep=c.repeat?Math.min(qty,babyReturn):0,deficit=c.repeat?Math.max(0,qty-babyReturn):qty;
 const feedQty=positive(c.feedQty),focus=qty*actions*Math.ceil(positive(c.nurtureFocus??breed.focus)),hours=positive(c.growHours)||breed.hours/(c.premium?2:1),outputs=[{id:c.mountMode==='grown'?m.grown:m.id,n:qty,quality:c.mountMode!=='grown'}];if(c.sellBabies&&babyReturn>keep)outputs.push({id:breed.id,n:babyReturn-keep});
 const inputs=[{id:breed.id,n:deficit},{id:c.feed,n:Math.ceil(feedQty*qty-1e-9)}];if(c.mountMode!=='grown')inputs.push(...m.mats.filter(x=>x.id!==m.grown).map(x=>({...x,n:x.n*qty})));
 return {valid:qty>0&&feedQty>0&&!!c.feed,reason:'Укажите корм и полный расход на одного зверя за выращивание.',inputs,outputs,silver:0,extra:(c.mountMode==='grown'?0:positive(c.fee)+m.silver)*qty,focus,hours,babyReturn,keep,deficit,seedStock:c.repeat?{id:breed.id,n:qty}:null,investment:positive(c.investment),expected:true};
}
function totals(plan,c,quote){if(plan.valid===false)return {...plan,ready:false,missing:[]};const tax=clamp(c.tax??4,100),setup=c.saleMode==='order'?clamp(c.setup??2.5,100):0,missing=[];function price(row,side){const city=side==='buy'?c.buyCity:c.sellCity,q=row.quality?Math.max(1,Math.min(5,count(c.quality)||1)):1,key=[city,side,row.id,q].join('|'),manual=c.prices&&Object.hasOwn(c.prices,key),p=manual?{price:positive(c.prices[key]),manual:true}:quote(row.id,side,city,q);if(row.n>0&&!(p?.price>0))missing.push(row.id);return {...row,city,side,quality:q,...p,price:positive(p?.price),total:row.n*positive(p?.price)};}
 const inputs=plan.inputs.filter(r=>r.n>0).map(r=>price(r,'buy')),outputs=plan.outputs.filter(r=>r.n>0).map(r=>price(r,'sell'));const supplies=inputs.reduce((s,r)=>s+r.total,0),gross=outputs.reduce((s,r)=>s+r.total,0),fees=gross*(tax+setup)/100,cost=supplies+positive(plan.extra)+positive(c.transport)+positive(c.other),income=gross-fees+positive(plan.silver),profit=income-cost;
 const seedStock=plan.seedStock?price(plan.seedStock,'buy'):null,investment=positive(plan.investment)+(seedStock?.total||0),requiredCash=cost+investment;
 return {...plan,inputs,outputs,supplies,gross,fees,cost,income,profit,investment,requiredCash,netCash:profit-investment,roi:cost?profit/cost*100:0,perDay:plan.hours?profit/plan.hours*24:null,silverPerFocus:plan.focus?profit/plan.focus:null,missing:[...new Set(missing)],ready:!missing.length&&inputs.length>0,liquidity:outputs.map(x=>({id:x.id,daily:x.daily||0,days:x.daily?x.n/x.daily:null,manual:!!x.manual}))};
}
const api={route,journal,enchant,salvage,mount,totals};root.EconomyMath=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
